var THEME_ORDER = ['mais60', 'desban', 'lifecode'];
var LEADS_STORAGE_KEY = 'mais60_leads';

// URL do Google Apps Script (Web App) que recebe os leads e grava na planilha
// central. Fica vazio até você publicar o script — veja o passo a passo que
// o Claude te passou. Enquanto estiver vazio, os leads continuam sendo
// salvos normalmente no tablet (localStorage), só não são enviados pra fora.
var LEADS_WEBHOOK_URL = 'https://script.google.com/macros/s/AKfycbxk9F9uyasXzqky1P9s_kflHsMT82LBnh4gNT37QLYQLY_8c69xQaXe_tV4_cLRU3LPyA/exec';

function generateLeadId(){
  return 'l' + Date.now().toString(36) + Math.random().toString(36).slice(2, 8);
}

// Envio "melhor esforço": como o Apps Script não devolve cabeçalhos CORS,
// usamos mode:'no-cors' (não dá pra ler a resposta, só saber se a rede
// aceitou o envio). O registro sempre permanece salvo no localStorage do
// tablet também — a planilha é uma cópia central, não substitui o backup local.
function sendLeadToSheet(record){
  if (!LEADS_WEBHOOK_URL) return Promise.reject(new Error('LEADS_WEBHOOK_URL não configurada'));
  return fetch(LEADS_WEBHOOK_URL, {
    method: 'POST',
    mode: 'no-cors',
    headers: { 'Content-Type': 'text/plain;charset=utf-8' },
    body: JSON.stringify(record)
  });
}

// Tenta reenviar para a planilha qualquer lead salvo localmente que ainda
// não foi confirmado como enviado (ex: tablet sem wifi no momento do jogo).
// Chamar no carregamento do hub e do jogo cobre o caso de reconectar depois.
function syncPendingLeads(){
  if (!LEADS_WEBHOOK_URL) return;
  var list;
  try{ list = JSON.parse(localStorage.getItem(LEADS_STORAGE_KEY) || '[]'); }
  catch(e){ return; }
  list.forEach(function(lead){
    if (lead.enviado) return;
    sendLeadToSheet(lead).then(function(){
      lead.enviado = true;
      try{ localStorage.setItem(LEADS_STORAGE_KEY, JSON.stringify(list)); }catch(e){}
    }).catch(function(){ /* segue pendente, tenta de novo na próxima carga de página */ });
  });
}
